from functools import lru_cache

@lru_cache(maxsize=None)
def climb(n):
    if n <= 1:
        return 1
    return climb(n - 1) + climb(n - 2)

# Manual memoization
def climb_memo(n, memo={}):
    if n in memo: return memo[n]
    if n <= 1: return 1
    memo[n] = climb_memo(n-1, memo) + climb_memo(n-2, memo)
    return memo[n]

